    /**
    * Calls:
    * 1 - (201) POST:/petclinic/api/owners
    * 2 - (404) POST:/petclinic/api/owners/{ownerId}/pets
    * Using 7 examples:
    *   (-) BODY -> 1
    *   (-) BODY -> 6085551023
    *   (-) BODY -> Franklin
    *   (-) BODY -> George
    *   (-) BODY -> Leo
    *   (-) BODY -> Madison
    *   (-) BODY -> cat
    */
    @Test @Timeout(60)
    public void test_36_postOnPetsReturns404() throws Exception {
        
        ValidatableResponse res_0 = given().accept("application/json")
                .contentType("application/json")
                .body(" { " + 
                    " \"firstName\" : \"George\", " + 
                    " \"lastName\" : \"Franklin\", " + 
                    " \"address\" : \"9Xfn6PutG2ijHO\", " + 
                    " \"city\" : \"Madison\", " + 
                    " \"telephone\" : \"6085551023\" " + 
                    " } ")
                .post(baseUrlOfSut + "/petclinic/api/owners")
                .then()
                .statusCode(201)
                .assertThat()
                .contentType("application/json")
                .body("'firstName'", containsString("George"))
                .body("'lastName'", containsString("Franklin"))
                .body("'address'", containsString("9Xfn6PutG2ijHO"))
                .body("'city'", containsString("Madison"))
                .body("'telephone'", containsString("6085551023"))
                .body("'pets'.size()", equalTo(0));
        String location_owners__2 = res_0.extract().header("location");
        assertTrue(isValidURIorEmpty(location_owners__2));
        
        given().accept("*/*")
                .contentType("application/json")
                .body(" { " + 
                    " \"name\" : \"Leo\", " + 
                    " \"birthDate\" : \"1946-00-03\", " + 
                    " \"type\" : { " + 
                    " \"name\" : \"cat\", " + 
                    " \"id\" : 1 " + 
                    " } " + 
                    " } ")
                .post(resolveLocation(location_owners__2, baseUrlOfSut + "/petclinic/api/owners/589/pets"))
                .then()
                .statusCode(404)
                .assertThat()
                .contentType("text/html");
        
        // Cleanup actions
        given().accept("*/*")
                .delete(resolveLocation(location_owners__2, baseUrlOfSut + "/petclinic/api/owners/106"))
                .then()
                .statusCode(404)
                .assertThat()
                .contentType("text/html");
    }
    
    
